export function calculateRetentionDeduction(retained: { isCapped: boolean; officialPrice?: number }[], ruleset?: any): {
  totalDeduction: number;
  cappedCount: number;
  uncappedCount: number;
  rtmCards: number;
} {
  let cappedCount = 0;
  let uncappedCount = 0;
  let totalDeduction = 0;

  for (const p of retained) {
    if (p.isCapped) {
      cappedCount++;
    } else {
      uncappedCount++;
    }
    totalDeduction += (p.officialPrice || (p.isCapped ? 180000000 : 40000000));
  }

  const rtmCards = Math.max(0, Math.min(6, 25 - (cappedCount + uncappedCount)));
  return { totalDeduction, cappedCount, uncappedCount, rtmCards };
}
